SET LOCAL ROLE ws_owner;
-- Approved narrow permissions, deny overrides still win. Assistants receive no default write permissions.
ALTER TABLE workspace.membership_permission_overrides DROP CONSTRAINT membership_permission_overrides_permission_check;
ALTER TABLE workspace.membership_permission_overrides ADD CONSTRAINT membership_permission_overrides_permission_check CHECK(permission IN('task.read','handover.create','handover.complete','inventory.read','inventory.manage','inventory.receive','inventory.use','inventory.adjust','inventory.dispose'));
ALTER TABLE workspace.membership_permission_overrides ADD CONSTRAINT s07_scope CHECK(left(permission,10)<>'inventory.'OR scope=CASE WHEN permission IN('inventory.receive','inventory.use')THEN 'own' ELSE 'school'END);
RESET ROLE;
INSERT INTO workspace.role_permission_defaults SELECT r,p,CASE WHEN p IN('inventory.receive','inventory.use')THEN 'own'ELSE 'school'END FROM unnest(ARRAY['SCHOOL_ADMIN','HEALTH_TEACHER'])r CROSS JOIN unnest(ARRAY['inventory.read','inventory.manage','inventory.receive','inventory.use','inventory.adjust','inventory.dispose'])p;
INSERT INTO workspace.role_permission_defaults VALUES('HEALTH_ASSISTANT','inventory.read','school');
SET LOCAL ROLE ws_owner;
CREATE TABLE workspace.shared_inventory_locations(location_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),school_id uuid NOT NULL REFERENCES workspace.schools,name text NOT NULL CHECK(length(name)BETWEEN 1 AND 60),active boolean NOT NULL DEFAULT true,version bigint NOT NULL DEFAULT 1 CHECK(version>0),created_by uuid NOT NULL,created_by_epoch integer NOT NULL,updated_by uuid NOT NULL,updated_by_epoch integer NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(school_id,location_id),UNIQUE(school_id,name),FOREIGN KEY(school_id,created_by,created_by_epoch)REFERENCES workspace.membership_terms,FOREIGN KEY(school_id,updated_by,updated_by_epoch)REFERENCES workspace.membership_terms);
CREATE TABLE workspace.shared_inventory_items(item_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),school_id uuid NOT NULL REFERENCES workspace.schools,item_name text NOT NULL CHECK(length(item_name)BETWEEN 1 AND 80),category text NOT NULL CHECK(length(category)<=40),specification text NOT NULL CHECK(length(specification)<=100),unit text NOT NULL CHECK(length(unit)BETWEEN 1 AND 12),minimum_quantity numeric NOT NULL CHECK(minimum_quantity BETWEEN 0 AND 1000000000 AND scale(minimum_quantity)<=3),storage_location_id uuid,active boolean NOT NULL DEFAULT true,created_by uuid NOT NULL,created_by_epoch integer NOT NULL,updated_by uuid NOT NULL,updated_by_epoch integer NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),version bigint NOT NULL DEFAULT 1 CHECK(version>0),UNIQUE(school_id,item_id),FOREIGN KEY(school_id,storage_location_id)REFERENCES workspace.shared_inventory_locations(school_id,location_id),FOREIGN KEY(school_id,created_by,created_by_epoch)REFERENCES workspace.membership_terms,FOREIGN KEY(school_id,updated_by,updated_by_epoch)REFERENCES workspace.membership_terms);
CREATE TABLE workspace.shared_inventory_lots(lot_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),school_id uuid NOT NULL,item_id uuid NOT NULL,expiry_date date CHECK(expiry_date IS NULL OR isfinite(expiry_date)),received_date date NOT NULL CHECK(isfinite(received_date)),quantity numeric NOT NULL CHECK(quantity BETWEEN 0 AND 1000000000 AND scale(quantity)<=3),state text NOT NULL DEFAULT 'AVAILABLE'CHECK(state IN('AVAILABLE','UNUSABLE')),version bigint NOT NULL DEFAULT 1 CHECK(version>0),created_by uuid NOT NULL,created_by_epoch integer NOT NULL,created_at timestamptz NOT NULL DEFAULT clock_timestamp(),updated_at timestamptz NOT NULL DEFAULT clock_timestamp(),UNIQUE(school_id,lot_id),UNIQUE(school_id,item_id,lot_id),FOREIGN KEY(school_id,item_id)REFERENCES workspace.shared_inventory_items(school_id,item_id),FOREIGN KEY(school_id,created_by,created_by_epoch)REFERENCES workspace.membership_terms);
CREATE TABLE workspace.shared_inventory_movements(movement_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),school_id uuid NOT NULL,item_id uuid NOT NULL,lot_id uuid NOT NULL,type text NOT NULL CHECK(type IN('RECEIVE','USE','ADJUST','DISPOSE','STATE')),quantity_before numeric NOT NULL CHECK(quantity_before>=0),delta numeric NOT NULL,quantity_after numeric NOT NULL CHECK(quantity_after BETWEEN 0 AND 1000000000),actor_membership_id uuid NOT NULL,actor_epoch integer NOT NULL,request_id uuid NOT NULL,lot_version bigint NOT NULL,reason text NOT NULL CHECK(length(reason)<=80),created_at timestamptz NOT NULL DEFAULT clock_timestamp(),CHECK(quantity_before+delta=quantity_after),UNIQUE(school_id,lot_id,lot_version),FOREIGN KEY(school_id,item_id,lot_id)REFERENCES workspace.shared_inventory_lots(school_id,item_id,lot_id),FOREIGN KEY(school_id,actor_membership_id,actor_epoch)REFERENCES workspace.membership_terms);
CREATE INDEX s07_items_search ON workspace.shared_inventory_items(school_id,active,category,item_name);
CREATE INDEX s07_lots_fefo ON workspace.shared_inventory_lots(school_id,item_id,expiry_date,lot_id);
CREATE INDEX s07_movements_item ON workspace.shared_inventory_movements(school_id,item_id,created_at DESC);
DO $$DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['shared_inventory_locations','shared_inventory_items','shared_inventory_lots','shared_inventory_movements']LOOP EXECUTE format('ALTER TABLE workspace.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE workspace.%I FORCE ROW LEVEL SECURITY',t);EXECUTE format('REVOKE ALL ON workspace.%I FROM PUBLIC,anon,authenticated',t);EXECUTE format('GRANT SELECT,INSERT ON workspace.%I TO ws_runtime',t);END LOOP;END$$;
GRANT UPDATE ON workspace.shared_inventory_locations,workspace.shared_inventory_items,workspace.shared_inventory_lots TO ws_runtime;
RESET ROLE;
